 static Bounds BoundsOf(Transform t){var rs=t.GetComponentsInChildren<MeshRenderer>().Where(r=>r.GetComponent<TMPro.TMP_Text>()==null).ToArray();var b=new Bounds(t.position,Vector3.zero);if(rs.Length>0){b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);}return b;}
 Transform Hand(string name,Vector3 at,Material mat){var hand=new GameObject(name).transform;hand.SetParent(view.transform,false);hand.localPosition=at;
 Part(hand,"Palm",PrimitiveType.Cube,Vector3.zero,new Vector3(.095f,.045f,.1f),mat);
 var sleeve=new Material(propMaterial){name="GS Hand Outfit",color=GridShiftCharacter.Current.outfit>=0?GridShiftCharacter.OutfitColors[GridShiftCharacter.Current.outfit]:new Color(.08f,.2f,.38f)};
 ownedMaterials.Add(sleeve);Part(hand,"Forearm",PrimitiveType.Cube,new Vector3(0,-.025f,-.17f),new Vector3(.075f,.065f,.25f),mat);
