 for(int i=0;i<4;i++){float length=i==0?.065f:i==3?.055f:.08f;var finger=new GameObject("Finger "+i).transform;finger.SetParent(hand,false);finger.localPosition=new Vector3((i-1.5f)*.023f,0,.045f);Part(finger,"Proximal phalanx",PrimitiveType.Cube,new Vector3(0,0,length*.25f),new Vector3(.019f,.028f,length*.5f),mat);Part(finger,"Fingertip",PrimitiveType.Cube,new Vector3(0,-.003f,length*.75f),new Vector3(.018f,.025f,length*.5f),mat);}
 return hand;}
 void LieOnBed(){if(station==null||animator==null)return;
 var mattress=station.GetComponentsInChildren<MeshRenderer>().FirstOrDefault(r=>r.name.StartsWith("Mattress"));if(mattress==null)return;
 var pillow=station.GetComponentsInChildren<MeshRenderer>().FirstOrDefault(r=>r.name.StartsWith("Pillow"));var bed=mattress.bounds;sleepCenter=new Vector3(bed.center.x,bed.max.y+.09f,bed.center.z);sleepHead=pillow!=null?Vector3.ProjectOnPlane(pillow.bounds.center-bed.center,Vector3.up).normalized:-station.right;if(sleepHead.sqrMagnitude<.5f)sleepHead=Vector3.back;
 sleepingBody=transform.Find("Player customized appearance");if(sleepingBody==null){sleepingBody=animator.GetBoneTransform(HumanBodyBones.Hips);if(sleepingBody==null)return;while(sleepingBody.parent!=null&&sleepingBody.parent!=transform)sleepingBody=sleepingBody.parent;if(sleepingBody==transform||player.CameraTransform.IsChildOf(sleepingBody)){sleepingBody=null;return;}}
 bodyPosition=sleepingBody.localPosition;bodyRotation=sleepingBody.localRotation;bodyScale=sleepingBody.localScale;
 var lying=Quaternion.LookRotation(Vector3.up,sleepHead);var turn=lying*Quaternion.Inverse(transform.rotation);sleepingBody.SetPositionAndRotation(sleepCenter-sleepHead*.85f+turn*(sleepingBody.position-transform.position),turn*sleepingBody.rotation);
 routineCamera=player.CameraTransform.GetComponent<Camera>();if(routineCamera!=null){cameraMask=routineCamera.cullingMask;routineCamera.cullingMask=transform.Find("Player customized appearance")!=null?routineCamera.cullingMask|(1<<8):(routineCamera.cullingMask|(1<<7))&~(1<<8);}view.SetActive(false);
