 void RestSleepingArms(){if(animator==null||!animator.isHuman)return;foreach(bool leftSide in new[]{true,false}){var upper=animator.GetBoneTransform(leftSide?HumanBodyBones.LeftUpperArm:HumanBodyBones.RightUpperArm);var lower=animator.GetBoneTransform(leftSide?HumanBodyBones.LeftLowerArm:HumanBodyBones.RightLowerArm);var hand=animator.GetBoneTransform(leftSide?HumanBodyBones.LeftHand:HumanBodyBones.RightHand);if(upper==null||lower==null||hand==null)continue;upper.rotation=Quaternion.FromToRotation(lower.position-upper.position,-sleepHead)*upper.rotation;lower.rotation=Quaternion.FromToRotation(hand.position-lower.position,(-sleepHead+Vector3.up*.1f).normalized)*lower.rotation;}}
 static Transform Part(Transform root,string name,PrimitiveType type,Vector3 at,Vector3 scale,Material material){var template=GridShiftSceneTemplates.Find(root.gameObject.scene,"prop-"+name);if(template!=null){var model=Instantiate(template,root,false);model.name=name;model.transform.localPosition=at+template.transform.localPosition;return model.transform;}var g=GameObject.CreatePrimitive(type);g.name=name;g.transform.SetParent(root,false);g.transform.localPosition=at;g.transform.localScale=scale;g.GetComponent<Collider>().enabled=false;g.GetComponent<Renderer>().sharedMaterial=material;return g.transform;}
