 void LateUpdate(){if(disposed||player==null)return;float t=Time.time-started,blend=Mathf.Clamp01(t*3);if(kind=="wash"||kind=="shower"||kind=="cook"||kind=="eat"){var b=station!=null?BoundsOf(station):new Bounds(player.transform.position+player.transform.forward,Vector3.one);var waterControl=kind=="shower"?station?.Find("Bath water control"):null;var at=waterControl!=null?waterControl.position:kind=="eat"?player.CameraTransform.position+player.transform.forward*2:kind=="cook"?new Vector3(b.center.x,b.max.y+.1f,b.center.z):new Vector3(b.center.x,player.transform.position.y+(kind=="wash"?1f:1.35f),b.center.z);var delta=at-player.CameraTransform.position;if(delta.sqrMagnitude>.1f)player.CameraTransform.rotation=Quaternion.Slerp(player.CameraTransform.rotation,Quaternion.LookRotation(delta),Time.deltaTime*5);}if(kind=="wash"||kind=="shower"){left.localPosition=new Vector3(-.085f+Mathf.Sin(t*9)*.035f,-.24f,.5f);right.localPosition=new Vector3(.085f-Mathf.Sin(t*9)*.035f,-.24f,.53f);left.localRotation=Quaternion.Euler(0,0,Mathf.Sin(t*9)*25);right.localRotation=Quaternion.Euler(0,0,-Mathf.Sin(t*9)*25);}else if(kind=="eat")right.localPosition=new Vector3(.15f,-.26f+Mathf.Max(0,Mathf.Sin(t*3))*.2f,.47f-Mathf.Max(0,Mathf.Sin(t*3))*.22f);else if(kind=="cook")right.localPosition=new Vector3(.16f+Mathf.Sin(t*6)*.07f,-.3f,.53f+Mathf.Cos(t*6)*.04f);else if(kind=="sleep"&&sleepingBody!=null){RestSleepingArms();player.CameraTransform.position=sleepCenter+Vector3.up*2.1f+Vector3.Cross(Vector3.up,sleepHead)*2.3f;player.CameraTransform.rotation=Quaternion.LookRotation(sleepCenter+sleepHead*.1f-player.CameraTransform.position,Vector3.up);}else if(kind=="relax"){player.CameraTransform.localPosition=cameraPosition+Vector3.down*.45f*blend;var tv=Object.FindObjectsByType<GridShiftHomeTV>(FindObjectsSortMode.None).OrderBy(x=>(x.transform.position-transform.position).sqrMagnitude).FirstOrDefault();if(tv!=null){var screen=tv.transform.Find("Screen");var at=screen!=null?BoundsOf(screen).center:t