 public void Dispose(){if(disposed)return;disposed=true;if(sleepingBody!=null){sleepingBody.localPosition=bodyPosition;sleepingBody.localRotation=bodyRotation;sleepingBody.localScale=bodyScale;}if(routineCamera!=null)routineCamera.cullingMask=cameraMask;if(player!=null&&player.CameraTransform!=null){player.CameraTransform.localPosition=cameraPosition;player.CameraTransform.localRotation=cameraRotation;}foreach(var pose in bones)if(pose.bone!=null)pose.bone.localRotation=pose.rotation;if(animator!=null)animator.enabled=wasAnimated;if(view!=null)Destroy(view);if(world!=null)Destroy(world);foreach(var material in ownedMaterials)if(material!=null)Destroy(material);ownedMaterials.Clear();Destroy(this);}
